/* @autogenerated */
import { Component, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { provideRouter } from '@angular/router';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { of } from 'rxjs';
import { AppStateService } from '@shared/context/state/app-state.service';
import { describeError, ErrorPageComponent } from './error-page.component';

describe('describeError', () => {
  it('uses a kind and image per known status', () => {
    expect(describeError({ status: 404 })).toEqual(
      jasmine.objectContaining({ kind: 'error_404', image: 'error-404.png' }),
    );
    expect(describeError({ status: 0 }).kind).toBe('error_0');
  });

  it('gives 5xx their own text, different from 404', () => {
    const e503 = describeError({ status: 503 });
    expect(e503.kind).toBe('error_5xx');
    expect(e503.image).toBe('error-unknown.png');
    expect(e503.kind).not.toBe(describeError({ status: 404 }).kind);
  });

  it('distinguishes 422 for missing required data', () => {
    expect(describeError({ status: 422, error: [{ description: 'not-empty' }] })).toEqual(
      jasmine.objectContaining({ kind: 'no_empty_error_422', image: 'error-422-no-empty.png' }),
    );
  });

  it('falls back to unknown for other statuses and errors without status', () => {
    expect(describeError({ status: 418 }).kind).toBe('error_unknown');
    expect(describeError(new Error('boom')).kind).toBe('error_unknown');
  });

  it('describes the absence of error as no content', () => {
    expect(describeError(undefined)).toEqual(jasmine.objectContaining({ kind: 'no_content', detail: null }));
  });

  it('keeps the technical detail and traceId for the folded section', () => {
    const d = describeError({ status: 500, url: '/api/x', error: { code: 42 }, traceId: 'abc' });
    expect(d.detail).toBe('HTTP 500 · /api/x · {"code":42}');
    expect(d.traceId).toBe('abc');
    expect(describeError({ status: 400, error: { message: 'Boom' } }).detail).toBe('HTTP 400 · Boom');
  });
});

@Component({
  standalone: true,
  imports: [ErrorPageComponent],
  template: `<app-page-error [error]="error()"><button class="extra">extra</button></app-page-error>`,
})
class HostComponent {
  error = signal<any>({ status: 503, error: { secret: 'payload' }, traceId: 'trace-1' });
}

describe('ErrorPageComponent', () => {
  beforeEach(() => {
    TestBed.configureTestingModule({
      imports: [
        HostComponent,
        TranslocoTestingModule.forRoot({
          langs: {
            en: {
              errors: {
                page: {
                  home: 'Home',
                  details: 'Details',
                  traceId: 'Ref',
                  error_404: { title: 'Not found', message: 'Gone' },
                  error_5xx: { title: 'Unavailable', message: 'Try later' },
                },
              },
            },
          },
          translocoConfig: { availableLangs: ['en'], defaultLang: 'en' },
        }),
      ],
      providers: [
        provideRouter([]),
        { provide: AppStateService, useValue: { language: of('es'), tenant: of('main') } },
      ],
    });
  });

  function render(error: any) {
    const fixture = TestBed.createComponent(HostComponent);
    fixture.componentInstance.error.set(error);
    fixture.detectChanges();
    return fixture.nativeElement as HTMLElement;
  }

  it('translates the texts and shows 404 and 503 differently', () => {
    expect(render({ status: 404 }).querySelector('h2')!.textContent).toBe('Not found');
    expect(render({ status: 503 }).querySelector('h2')!.textContent).toBe('Unavailable');
  });

  it('keeps the technical detail inside a folded <details>', () => {
    const el = render({ status: 503, error: { secret: 'payload' }, traceId: 'trace-1' });
    const details = el.querySelector('details')!;

    expect(details.open).toBeFalse();
    expect(details.textContent).toContain('trace-1');
    expect(el.querySelector('p:not(details p)')!.textContent).not.toContain('payload');
  });

  it('links home with language and tenant and projects extra actions', () => {
    const el = render({ status: 404 });

    expect(el.querySelector('a')!.getAttribute('href')).toBe('/es/main');
    expect(el.querySelector('button.extra')).not.toBeNull();
  });
});
